output_text:
[
  {
    "id": "entrance_cart_checkout",
    "text": "A shopper must check out the entrance cart before beginning the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_stand": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "checkout_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_stand",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_entrance_cart"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "It is forbidden to take shelf items unless the shopper is currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carried_goods",
    "text": "Items should not be carried by hand; shoppers must keep goods in a cart rather than becoming hand-full.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After any item is picked up while using a cart, the cart must eventually be returned to the north-west cart bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "collect_shelf_item_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "hasCart",
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_shelf_item_with_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A cart may be put down only at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "outside_return_bay": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "hasCart",
              "outside_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden to leave the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "exit_cell",
              "hasCart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "do_not_roll_cart_past_return_bay",
    "text": "Once a shopper reaches the cart-return bay with a cart, they must leave it there rather than moving away with it.",
    "abstraction": {
      "state_properties": {
        "at_return_bay_with_cart": {
          "and": [
            "at(0,1)",
            "hasCart"
          ]
        }
      },
      "events": {
        "move_cart_from_return_bay": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_cart_from_return_bay"
    }
  },
  {
    "id": "do_not_reclaim_returned_cart",
    "text": "After a cart has been stationed in the return bay, shoppers should not pick that returned cart up again.",
    "abstraction": {
      "state_properties": {
        "returned_cart_waiting": "cartAt(0,1)"
      },
      "events": {
        "reclaim_returned_cart": {
          "pre": {
            "and": [
              "returned_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "reclaim_returned_cart"
    }
  }
]
